import{_ as c,C as r,o as E,c as d,a3 as l,E as t,j as a,a as i,b as B,w as n,a6 as A}from"./chunks/framework.Ba39LDvt.js";const C=JSON.parse('{"title":"电源管理与功率电子","description":"认识上科大的电源管理芯片、算力电源、无线传能与能量收集研究。","frontmatter":{"title":"电源管理与功率电子","description":"认识上科大的电源管理芯片、算力电源、无线传能与能量收集研究。"},"headers":[],"relativePath":"research/power.md","filePath":"research/power.md","lastUpdated":1795525517000}'),u={name:"research/power.md"};function p(f,e,g,m,b,_){const s=r("FacultyList"),o=r("CourseTable"),h=r("Mermaid");return E(),d("div",null,[e[1]||(e[1]=l('<h1 id="电源管理与功率电子" tabindex="-1">电源管理与功率电子 <a class="header-anchor" href="#电源管理与功率电子" aria-label="Permalink to &quot;电源管理与功率电子&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>功率电子（Power Electronics）研究电能的变换与控制，电源管理集成电路（Power Management IC，PMIC）则把部分控制、驱动或功率功能集成到芯片中。它连接半导体器件、控制理论、磁性元件、散热与负载需求，尺度可以从微瓦级能量收集延伸到大功率变换系统。高效率不是唯一目标，动态响应、可靠性和电磁兼容同样决定系统能否工作。</p><p>核心研究问题包括：</p><ul><li>如何选择变换拓扑、开关频率和器件，平衡损耗、体积与成本？</li><li>输入与负载变化时，怎样保证稳定性和快速响应？</li><li>宽禁带器件的高速开关怎样影响驱动、寄生与电磁干扰？</li><li>算力负载的快速电流变化如何影响供电网络与电源控制？</li><li>无线传能和能量收集在弱耦合、低输入条件下怎样维持有效供能？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大的相关公开研究分布在电气与器件方向。王浩宇的 PEARL 实验室研究电力电子、电源管理芯片、算力电源与电动汽车；傅旻帆关注电力电子、无线传能、脑机接口充电、功率 IC、射频功放、电磁兼容及宽禁带器件应用。两条线都与电能转换有关，但具体系统规模与应用约束需要看近期论文。</p><p>梁俊睿关注环境能量收集、无源物联网、功率管理集成电路与机电一体化，连接低功耗传感和能源系统。邹新波的宽禁带半导体功率器件与陷阱物性研究提供器件层入口。选择课题时，可先区分自己更关注“器件为何损耗”“电路如何转换”还是“系统怎样控制”，再选择合适的基础与实践。</p>',8)),t(s,{dir:"power"}),e[2]||(e[2]=a("h2",{id:"相关上科大课程",tabindex:"-1"},[i("相关上科大课程 "),a("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),e[3]||(e[3]=a("p",null,"电路基础之后可以从 EE171 进入电力电子，并用建模控制与高级变换课程继续深入；实际开课和选课条件以当学期公布为准。",-1)),t(o,{codes:"EE111,EE115A,EE171,EE270,EE273,EE291H,EE120"}),e[4]||(e[4]=a("h2",{id:"知识前置",tabindex:"-1"},[i("知识前置 "),a("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),e[5]||(e[5]=a("p",null,"这是概念学习路径，不替代正式先修表；控制理论、磁性元件与散热知识应按应用补充。",-1)),(E(),B(A,null,{default:n(()=>[t(h,{id:"mermaid-64",class:"mermaid",graph:"graph%20LR%0A%20%20A%5B%22EE111%20%E7%94%B5%E8%B7%AF%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20B%5B%22EE171%20%E7%94%B5%E5%8A%9B%E7%94%B5%E5%AD%90%22%5D%0A%20%20A%20--%3E%20C%5B%22EE115A%20%E6%A8%A1%E6%8B%9F%E7%94%B5%E8%B7%AF%22%5D%0A%20%20D%5B%22EE150%20%E4%BF%A1%E5%8F%B7%E4%B8%8E%E7%B3%BB%E7%BB%9F%22%5D%20--%3E%20E%5B%22EE270%20%E7%94%B5%E5%8A%9B%E7%94%B5%E5%AD%90%E5%8F%98%E6%8D%A2%E5%99%A8%E5%BB%BA%E6%A8%A1%E4%B8%8E%E6%8E%A7%E5%88%B6%22%5D%0A%20%20B%20--%3E%20E%0A%20%20B%20--%3E%20F%5B%22EE273%20%E9%AB%98%E7%BA%A7%E7%94%B5%E8%83%BD%E5%8F%98%E6%8D%A2%E6%8A%80%E6%9C%AF%22%5D%0A%20%20G%5B%22EE120%20%E5%8D%8A%E5%AF%BC%E4%BD%93%E5%99%A8%E4%BB%B6%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20H%5B%22%E5%8A%9F%E7%8E%87%E5%99%A8%E4%BB%B6%E4%B8%8E%E5%BC%80%E5%85%B3%E7%89%B9%E6%80%A7%22%5D%0A%20%20C%20--%3E%20I%5B%22%E9%A9%B1%E5%8A%A8%E4%B8%8E%E7%94%B5%E6%BA%90%E7%AE%A1%E7%90%86%E7%94%B5%E8%B7%AF%22%5D%0A%20%20E%20--%3E%20J%5B%22%E7%94%B5%E6%BA%90%E4%B8%8E%E5%8A%9F%E7%8E%87%E7%94%B5%E5%AD%90%E7%A0%94%E7%A9%B6%22%5D%0A%20%20F%20--%3E%20J%0A%20%20H%20--%3E%20J%0A%20%20I%20--%3E%20J%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=l('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：Virginia Tech 的 CPES、ETH Zurich 的相关电力电子团队，以及清华、浙江大学的相关团队，可用于观察器件、变换器与控制的不同研究层次。</li><li><strong>产业参照</strong>：Infineon、Texas Instruments、Analog Devices 的功率器件与电源产品，以及电动汽车、服务器电源等应用生态；不表示上科大合作关系。</li><li><strong>会议与期刊</strong>：APEC、ECCE，以及 IEEE Transactions on Power Electronics（TPEL）、IEEE Journal of Emerging and Selected Topics in Power Electronics；集成电源电路也可关注 ISSCC、CICC、JSSC。</li></ul><p>比较效率时必须看输入输出电压、负载范围、开关频率、器件温度和外围元件。峰值效率不能代表全负载表现，芯片控制电路的功耗也不能直接代替整机损耗。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/analog">模拟自学</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/device">器件自学</a>：分别补电路控制接口与功率器件基础。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/foundations">电路与数学基础</a>：复习动态系统和频域分析。</li><li><a href="https://www.ieee-pels.org/" target="_blank" rel="noreferrer">IEEE Power Electronics Society</a>：领域会议、期刊与教育入口。</li><li><a href="https://www.ti.com/" target="_blank" rel="noreferrer">Texas Instruments</a>：用电源产品数据手册和官方应用资料练习规格分析。</li></ul><p>入门可先分析低压 Buck 变换器，列出能量流、关键波形和损耗项，再研究闭环响应。涉及市电、高压、大电流和储能元件的实验必须在合规场地与指导下进行，不能照搬网上电路直接接电。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎相关课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a> 补充“组里在做什么”、公开的低压实验与仿真入门路线、进组准备建议；安全规范应引用实验室正式要求。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/wanghy/main.htm" target="_blank" rel="noreferrer">王浩宇学院主页</a>、<a href="https://pearl.shanghaitech.edu.cn" target="_blank" rel="noreferrer">PEARL</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/fumf/main.htm" target="_blank" rel="noreferrer">傅旻帆学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/liangjr/main.htm" target="_blank" rel="noreferrer">梁俊睿学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/zouxb/main.htm" target="_blank" rel="noreferrer">邹新波学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：功率器件相关历史方向介绍。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>。</li></ul>',10))])}const P=c(u,[["render",p]]);export{C as __pageData,P as default};
